import { cn } from "@/lib/utils";

import { FIGURE, H1, H2, MONOGRAM_VIEWBOX } from "./logo-paths";

/**
 * The Haya & Haze logo. This is the ONE place the logo is defined for the site.
 *
 * Design, after the client reference: a lowercase serif "hh" monogram — a deep "h" and a
 * camel "h" — joined by a line-drawn woman in a hijab, seen from behind, her cloak
 * flowing down between the letters.
 *
 * The outlines come from `logo-paths.ts`, generated by `npm run brand:logo` together with
 * the static files in /public/brand (SVG, PNG, favicon, social image).
 *
 * To swap in final artwork: replace the SVG in <Monogram /> (or render an <img> pointing
 * at a file in /public/brand) and keep the same props.
 */
type Tone = "dark" | "light";

const INK: Record<Tone, { primary: string; accent: string; line: string; fill: string }> = {
  // for light backgrounds
  dark: { primary: "#4A2C2A", accent: "#B08F68", line: "#A58461", fill: "#FBF3EC" },
  // for dark backgrounds (footer, premium sections)
  light: { primary: "#FFF8F6", accent: "#D9BC95", line: "#E3C9A4", fill: "#4A342A" },
};

export function Monogram({ tone = "dark", className, title = "Haya & Haze" }: { tone?: Tone; className?: string; title?: string }) {
  const c = INK[tone];
  return (
    <svg
      viewBox={MONOGRAM_VIEWBOX} className={className} fill="none"
      {...(title ? { role: "img", "aria-label": title } : { "aria-hidden": true })}
    >
      <path d={H1} fill={c.primary} />
      <g stroke={c.line} strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
        <path d={FIGURE.drape} fill={c.fill} />
        <path d={FIGURE.head} fill={c.fill} />
        {FIGURE.folds.map((d, i) => <path key={i} d={d} opacity={i > 4 ? 0.7 : 1} />)}
      </g>
      <path d={H2} fill={c.accent} />
    </svg>
  );
}

export function Wordmark({ tone = "dark", className }: { tone?: Tone; className?: string }) {
  const c = INK[tone];
  return (
    <span className={cn("font-serif font-medium leading-none tracking-[0.02em] whitespace-nowrap", className)} style={{ color: c.primary }}>
      haya <span style={{ color: c.accent }}>&amp;</span> haze
    </span>
  );
}

/**
 * `lockup`   monogram above the wordmark with the "HIJAB & ABAYA" caption (footer, splash)
 * `inline`   monogram beside the wordmark (header)
 * `wordmark` text only
 * `mark`     monogram only
 */
export function Logo({
  variant = "inline", tone = "dark", className,
}: { variant?: "lockup" | "inline" | "wordmark" | "mark"; tone?: Tone; className?: string }) {
  const c = INK[tone];
  if (variant === "mark") return <Monogram tone={tone} className={cn("h-12 w-auto", className)} />;
  if (variant === "wordmark") return <Wordmark tone={tone} className={cn("text-3xl", className)} />;
  if (variant === "inline") {
    return (
      <span className={cn("inline-flex items-center gap-1.5 sm:gap-2", className)} role="img" aria-label="Haya & Haze">
        <Monogram tone={tone} className="h-10 w-auto sm:h-11 md:h-[52px]" title="" />
        <Wordmark tone={tone} className="text-[1.35rem] sm:text-[1.6rem] md:text-[1.9rem]" />
      </span>
    );
  }
  return (
    <span className={cn("inline-flex flex-col items-center", className)} role="img" aria-label="Haya & Haze, Hijab & Abaya">
      <Monogram tone={tone} className="h-28 w-auto" title="" />
      <Wordmark tone={tone} className="mt-3 text-5xl" />
      <span className="mt-3 flex items-center gap-3 text-[0.62rem] tracking-[0.42em]" style={{ color: c.accent }}>
        <span className="h-px w-8" style={{ background: c.accent }} />
        HIJAB &amp; ABAYA
        <span className="h-px w-8" style={{ background: c.accent }} />
      </span>
    </span>
  );
}
